"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[38980],{64085:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TurretGuiController","desc":"Drives the authored, generic `StarterGui.TurretGui` gunner HUD for any\\nturret. It holds nothing turret-specific: it shows while\\n`Signals.OnTurretMounted` carries a Model and reads only that model\'s\\nattributes:\\n\\n- `DisplayName` (string; fallback `model.Name:upper()`)\\n- `Ammo`, `MagazineSize` (no `MagazineSize` hides the count row, the bar\\n  and the `R RELOAD` hint part)\\n- `Reloading`, `ReloadEndsAt` (server clock, `workspace:GetServerTimeNow()`),\\n  `ReloadTime`\\n- `AmmoType` (train-ammo turrets): the `Max` label shows the party reserve\\n  (`ReplicatedStorage` attribute `TrainAmmo_<AmmoType>`) instead of\\n  `MagazineSize`; an empty magazine with an empty reserve shows `NO AMMO`\\n- Heat mode (replaces the ammo panel; active exactly when `MaxHeat` is a\\n  number): `Heat`, `MaxHeat`, `PeakHeat` (same unit as `Heat`), `Overheated`\\n\\n```\\nTurretGui (ScreenGui, IgnoreGuiInset)\\n\u251c\u2500\u2500 Crosshair (UIScale) { Image }\\n\u251c\u2500\u2500 AmmoPanel (UIScale) { Name, NumRow { Count, Max }, State, Bar { Fill } }\\n\u251c\u2500\u2500 Hint (UIScale) { LeaveHint, Sep1, ReloadHint, Sep2, FireHint }\\n\u251c\u2500\u2500 HeatBar (UIScale) { Glow { UIStroke }, Bar { Fill { UIGradient } }, OverheatLabel }\\n\u2514\u2500\u2500 FireButton (UIScale)\\n```\\n\\nThe crosshair is the exact screen centre the gunner\'s camera-centre ray\\nuses (`ViewportSize / 2`), hence `IgnoreGuiInset = true`. Its `Image` is the\\ncross image (`CrosshairConfig.CrossImage`), mint, amber while reloading, sized\\nby `CrosshairMath.crossSizePx` from the cone of `Signals.SetCrosshairSource`\\n(the shell turrets\' spread, the Schwarmfeuer salvo kick; no source = floor size),\\neased on the per-mount `RenderStepped`. Its size is real pixels, so the\\nCrosshair `UIScale` stays 1. The key hint is\\ndesktop only and the FIRE button touch only (`UserInputService.TouchEnabled`);\\nthe button fires `Signals.TurretTrigger(true/false)`. The per-turret\\nattribute connections and the bar\'s `RenderStepped` live in a `Janitor`\\nthat is cleaned on every `OnTurretMounted` change.\\n\\nHeat mode shows the lean `HeatBar` above the key hint (desktop) or above the\\nFIRE button (touch) and hides the ammo panel. The fill is `Heat / MaxHeat`\\nin hard colour bands (teal, amber from `HEAT_MID`, rust from\\n`PeakHeat / MaxHeat`). At the rust band a glow ring breathes and a sand band\\nsweeps the fill; while `Overheated` the fill blinks red and `OVERHEATED`\\nshows, with no glow. The glow, sweep and blink run on one `RenderStepped`\\nthat is bound only while one of them is visible.","realm":["Client"],"source":{"line":51,"path":"src/StarterPlayer/StarterPlayerScripts/TurretGuiController.client.luau"}}')}}]);